import re
bugs = {"merge_ranges", "chunk", "parse_kv", "to_cents"}
names = {"clamp", "merge_ranges", "median", "chunk", "running_total", "parse_kv", "dedupe_keep_last", "to_cents", "apply_discount", "top_n"}
found = {w for w in re.findall(r"[a-z_]+", open("findings.txt").read()) if w in names}
missed, extra = bugs - found, found - bugs
assert not missed and not extra, f"missed {sorted(missed)}, wrongly named {sorted(extra)}"
